do $$ declare t text; begin for t in select tablename from pg_tables where schemaname='public' loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create or replace function is_admin() returns boolean language sql stable as $$ select exists(select 1 from admin_users where email=auth.jwt()->>'email' and status='active' and role in('staff','admin','owner')) $$;
create or replace function is_owner() returns boolean language sql stable as $$ select exists(select 1 from admin_users where email=auth.jwt()->>'email' and status='active' and role='owner') $$;
