-- Baseline permissive public read/admin write policies for phase-1; tighten per environment as needed.
do $$ declare t text; begin for t in select tablename from pg_tables where schemaname='public' loop execute format('drop policy if exists public_read on public.%I',t); execute format('create policy public_read on public.%I for select using (true)',t); execute format('drop policy if exists admin_write on public.%I',t); execute format('create policy admin_write on public.%I for all using (is_admin()) with check (is_admin())',t); end loop; end $$;
